const fs = require('fs');
const cp = require('child_process');
const b64 = '';
const script = Buffer.from(b64, 'base64').toString('utf8');
const dest = '/home/node/.n8n/sicoob_recibos.js';
fs.writeFileSync(dest, script, 'utf8');
fs.chmodSync(dest, '755');

// Adicionar ao cron se nao existir
try {
  const cron = fs.readFileSync('/etc/cron.d/sicoob-sync', 'utf8');
  if (!cron.includes('sicoob_recibos')) {
    const line = '
*/15 7-23 * * * root docker exec n8n-n8n-1 node /home/node/.n8n/sicoob_recibos.js REAL=1 >> /var/log/sicoob_sync.log 2>&1
';
    fs.appendFileSync('/etc/cron.d/sicoob-sync', line);
  }
} catch(e) { /* cron fica no host, nao no container */ }

return [{json: {status: 'ok', bytes: script.length, path: dest}}];
